# === FiLM TRAINING FUNCTIONS ===


def run_stage2_film_training(
    pretrained_unet_weights_path,
    config: dict
):
    """
    ✅ FINAL CORRECTED FiLM-AWARE STAGE 2B DIAGNOSTIC FUNCTION ✅
    This version correctly extracts all parameters from the config dictionary
    and passes them to the loss function and training loop.
    """
    # === 1. Extract ALL parameters from config with defaults ===
    config_id = config.get('config_id', 'default_run')
    num_epochs_phase_b = config.get('num_epochs_phase_b', 15)
    batch_size = config.get('batch_size', 4)
    lr_unet = config.get('lr_unet', 1e-5)
    lr_film = config.get('lr_film', 1e-4)
    lr_frontend = config.get('lr_frontend_phase_b', 5e-5)
    lambda_gamma = config.get('lambda_gamma', 0.005)
    lambda_beta = config.get('lambda_beta', 0.0005)
    scheduler_type = config.get('scheduler', 'ReduceLROnPlateau')

    # --- ✅ CURRICULUM FIX: Extract curriculum parameters ---
    curriculum_simple_epochs = config.get('curriculum_simple_epochs', 0)
    start_simple = curriculum_simple_epochs > 0

    # Fixed parameters
    min_velocity = 1.5
    loss_fixed_weights = [1.0, 0.12, 0.007]
    weight_decay = 0.01
    weight_decay_film = 1e-3
    logmae_initial_c = 0.1

    print("=" * 80)
    print(f"🎬 STAGE 2B: FiLM DIAGNOSTIC RUN")
    print(f"   Config ID: {config_id}")
    print(f"   Curriculum: {'Enabled' if start_simple else 'Disabled'} ({curriculum_simple_epochs} simple epochs)")
    print("=" * 80)

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    if 'cuda' in str(device):
        configure_a100_stability()

    train_loader, val_loader = setup_phase2_data_loaders(batch_size=batch_size, num_workers=0)

    model = CompleteSincGAT_UNet(film_generator_mlp_type=config.get('film_generator_mlp_type', '2_layer')).to(device)

    # --- Pretrained Weights Loading ---
    print(f"📦 Loading pretrained model weights from: {pretrained_unet_weights_path}")
    checkpoint = torch.load(pretrained_unet_weights_path, map_location=device, weights_only=False)
    if 'model_state_dict' in checkpoint:
        model.load_state_dict(checkpoint['model_state_dict'], strict=True)
    else:
        model.load_state_dict(checkpoint, strict=True)
    print("✅ Pretrained weights loaded successfully.")


    criterion = RefinedLogSpaceMAEHybridLoss(
        min_velocity=min_velocity,
        initial_c_logmae=logmae_initial_c,
        fixed_weights_list=loss_fixed_weights,
        lambda_gamma_res=lambda_gamma,
        lambda_beta_res=lambda_beta,
        use_film_reg=True,
        start_simple=start_simple,
        curriculum_epochs=curriculum_simple_epochs
    ).to(device)

    experiment_name = f"{config_id}_PhaseB_FiLMFinetune"
    print(f"\n🎬 Running Phase 2b: FiLM Fine-tuning ({num_epochs_phase_b} epochs)")

    # --- Optimizer Setup ---
    optimizer_config = [
    {'params': model.shot_encoder.parameters(), 'lr': lr_frontend, 'weight_decay': weight_decay, 'group_name': 'SincNet', 'apply_warmup': True},     # ✅ RE-ENABLE
    {'params': model.gat_fusion.parameters(), 'lr': lr_frontend, 'weight_decay': weight_decay, 'group_name': 'GAT', 'apply_warmup': True},           # ✅ RE-ENABLE
    {'params': model.gat_context_layernorm.parameters(), 'lr': lr_film, 'weight_decay': weight_decay, 'group_name': 'GAT_Norm', 'apply_warmup': True}, # ✅ RE-ENABLE
    {'params': model.film_bottleneck_modulator.parameters(), 'lr': lr_film, 'weight_decay': weight_decay_film, 'group_name': 'FiLM', 'apply_warmup': True}, # ✅ RE-ENABLE
    {'params': model.unet.parameters(), 'lr': lr_unet, 'weight_decay': weight_decay, 'group_name': 'U-Net', 'apply_warmup': False}  # ✅ U-Net: No warmup
    ]

    # Check if SAM is requested and available
    # Check if SAM is requested and available
    use_sam = config.get('use_sam', False)
    sam_available = config.get('SAM_AVAILABLE', False)
    SAM_CLASS = config.get('SAM_CLASS', None)

    if use_sam and sam_available and SAM_CLASS is not None:
        sam_rho = config.get('sam_rho', 0.05)
        sam_adaptive = config.get('sam_adaptive', True)

        # ✅ CORRECT: Pass parameter groups and optimizer CLASS to SAM
        optimizer = SAM_CLASS(
            optimizer_config,          # Parameter groups (not model.parameters())
            torch.optim.AdamW,         # Optimizer CLASS (not instance)
            rho=sam_rho,              # SAM parameters
            adaptive=sam_adaptive
        )
        print(f"✅ Using SAM optimizer: rho={sam_rho}, adaptive={sam_adaptive}")
    else:
        # Standard optimizer
        optimizer = torch.optim.AdamW(optimizer_config)

        if use_sam:
            print("⚠️  SAM requested but not available, using standard AdamW")
    # --- Scheduler Setup ---
# --- Enhanced Scheduler Setup ---
    scheduler = None
    debug_scheduler_and_optimizer_state(None, optimizer, 0, "AFTER_OPTIMIZER_CREATION")
    if scheduler_type == 'ReduceLROnPlateau':
        # ✅ CRITICAL FIX: Use base_optimizer for SAM compatibility
        target_optimizer = optimizer.base_optimizer if hasattr(optimizer, 'base_optimizer') else optimizer
        scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
            target_optimizer,
            mode='min',
            factor=0.8,
            patience=3,
            threshold=0.001,
            min_lr=1e-8,
            verbose=True
        )
        print(f"   📉 ReduceLROnPlateau: factor=0.8, patience=3, threshold=0.001")
    elif scheduler_type == 'PlateauToCosine':
        # 🚀 NEW: Hybrid scheduler
        target_optimizer = optimizer.base_optimizer if hasattr(optimizer, 'base_optimizer') else optimizer
        plateau_kwargs = {
            'mode': 'min',
            'factor': config.get('plateau_factor', 0.8),
            'patience': config.get('plateau_patience', 3),
            'threshold': config.get('plateau_threshold', 0.001),
            'min_lr': 1e-8,
            'verbose': True
        }
        cosine_kwargs = {
            'T_max': config.get('cosine_T_max', 8),
            'eta_min': config.get('cosine_eta_min', 1e-8)
        }
        scheduler = PlateauToCosineScheduler(
            target_optimizer,
            plateau_kwargs=plateau_kwargs,
            cosine_kwargs=cosine_kwargs,
            lr_switch_threshold=config.get('lr_switch_threshold', 2.5e-05),
            threshold_group_index=config.get('threshold_group_index', 0),  # ✅ FINAL FIX: Monitor U-Net group
            verbose=True
        )
        print(f"   🚀 PlateauToCosine: threshold={config.get('lr_switch_threshold', 2.5e-05):.2e}, cosine_epochs={config.get('cosine_T_max', 8)}")
        debug_scheduler_and_optimizer_state(scheduler, optimizer, 0, "AFTER_PLATEAU_TO_COSINE_CREATION")
    elif scheduler_type == 'CosineAnnealingLR':
        target_optimizer = optimizer.base_optimizer if hasattr(optimizer, 'base_optimizer') else optimizer
        scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(target_optimizer, T_max=num_epochs_phase_b, eta_min=1e-7)
        print(f"   📈 CosineAnnealingLR: T_max={num_epochs_phase_b} epochs, eta_min=1e-7")
    elif scheduler_type == 'CosineAnnealingWarmRestarts':
        T_0 = config.get('T_0', 8)
        T_mult = config.get('T_mult', 1)
        eta_min = config.get('eta_min', 1e-8)

        target_optimizer = optimizer.base_optimizer if hasattr(optimizer, 'base_optimizer') else optimizer
        scheduler = torch.optim.lr_scheduler.CosineAnnealingWarmRestarts(
            target_optimizer, T_0=T_0, T_mult=T_mult, eta_min=eta_min, verbose=True
        )
        print(f"   📈 CosineAnnealingWarmRestarts: T_0={T_0} epochs, T_mult={T_mult}, eta_min={eta_min}")
    debug_scheduler_and_optimizer_state(scheduler, optimizer, 0, "BEFORE_TRAINING_STARTS")
    # --- ✅ TRAINING CALL FIX: Pass curriculum_simple_epochs correctly ---
    training_result = train_with_film_awareness(
        experiment_name=experiment_name,
        model=model,
        train_loader=train_loader,
        val_loader=val_loader,
        criterion=criterion,
        optimizer=optimizer,
        num_epochs=num_epochs_phase_b,
        device=device,
        calculate_mape_func=calculate_mape,
        lr_scheduler=scheduler,
        config=config,
        curriculum_simple_epochs=curriculum_simple_epochs  # Now properly defined!
    )

    print(f"✅ Phase 2b completed. Best MAPE: {training_result['best_mape']:.4f}%")

    return {
        'final_model_path': training_result['final_model_path'],
        'best_mape_phase_b': training_result['best_mape'],
        'training_history': training_result['history']
    }


def run_complete_film_workflow(
    stage1_epochs=45,
    stage1_batch_size=8,
    stage2_epochs_a=10,
    stage2_epochs_b=30,
    stage2_batch_size=4,
    film_generator_mlp_type='linear',
    experiment_name_prefix="Complete_FiLM_Workflow"
):
    """
    Complete two-stage workflow with FiLM integration.

    Stage 1: Pretrain U-Net on direct seismic->velocity mapping
    Stage 2: Fine-tune with FiLM-enhanced SincGAT-UNet architecture

    Args:
        stage1_epochs: Epochs for U-Net pretraining
        stage1_batch_size: Batch size for Stage 1
        stage2_epochs_a: Epochs for frontend training (Stage 2a)
        stage2_epochs_b: Epochs for FiLM fine-tuning (Stage 2b)
        stage2_batch_size: Batch size for Stage 2
        film_generator_mlp_type: 'linear' or '2_layer' FiLM generator
        experiment_name_prefix: Experiment name prefix

    Returns:
        Dictionary with complete workflow results
    """
    print("=" * 80)
    print(f"🎬 COMPLETE FiLM WORKFLOW: TWO-STAGE TRAINING")
    print("=" * 80)

    # === STAGE 1: U-Net Pretraining ===
    print(f"\n🏗️ STAGE 1: U-NET PRETRAINING")
    print("-" * 50)

    stage1_result = run_stage1_pretrain_unet(
        num_epochs=stage1_epochs,
        batch_size=stage1_batch_size,
        lr=1e-4,
        weight_decay=0.01,
        min_velocity=1.5,
        logmae_initial_c=0.1,
        loss_fixed_weights=[1.0, 0.12, 0.007],  # Champion weights
        experiment_name_prefix=f"{experiment_name_prefix}_Stage1"
    )

    if stage1_result is None:
        print("❌ Stage 1 failed. Cannot proceed to Stage 2.")
        return None

    stage1_weights_path, stage1_history = stage1_result
    print(f"✅ Stage 1 completed!")
    print(f"   Pretrained weights: {stage1_weights_path}")

    # === STAGE 2: FiLM-Enhanced Fine-tuning ===
    print(f"\n🎬 STAGE 2: FiLM-ENHANCED FINE-TUNING")
    print("-" * 50)

    stage2_result = run_stage2_film_training(
        pretrained_unet_weights_path=stage1_weights_path,
        num_epochs_phase_a=stage2_epochs_a,
        num_epochs_phase_b=stage2_epochs_b,
        batch_size=stage2_batch_size,
        lr_frontend_phase_a=1e-4,
        lr_frontend_phase_b=5e-5,
        lr_unet_finetune_phase_b=1e-5,
        lr_film_generator=1e-4,  # 10x U-Net LR for FiLM
        weight_decay=0.01,
        weight_decay_film=1e-3,  # Stronger regularization for FiLM
        min_velocity=1.5,
        logmae_initial_c=0.1,
        loss_fixed_weights=[1.0, 0.12, 0.007],  # Champion weights
        curriculum_start_simple=True,
        curriculum_total_epochs_for_simple_phase=2,
        experiment_name_prefix=f"{experiment_name_prefix}_Stage2",
        film_generator_mlp_type=film_generator_mlp_type,
        use_film_reg=True,  # CRITICAL: Enable FiLM regularization
        lambda_gamma_res=0.005,  # Research-backed λ values
        lambda_beta_res=0.0005,
        warmup_steps=1000,
        gradient_clip_film=1.0,
        gradient_clip_others=5.0,
        monitor_freq=50
    )

    if stage2_result is None:
        print("❌ Stage 2 failed.")
        return None

    print(f"✅ Complete FiLM workflow finished!")
    print(f"   Final MAPE: {stage2_result['best_mape_phase_b']:.4f}%")
    print(f"   FiLM model: {stage2_result['final_model_path']}")

    return {
        'stage1_weights_path': stage1_weights_path,
        'stage1_history': stage1_history,
        'stage2_result': stage2_result,
        'final_mape': stage2_result['best_mape_phase_b'],
        'final_model_path': stage2_result['final_model_path']
    }


def run_film_experiments_with_existing_weights(pretrained_weights_path):
    """
    Run FiLM experiments using existing Stage 1 pretrained weights.

    This function allows you to explore FiLM configurations without
    re-running Stage 1 pretraining.

    Args:
        pretrained_weights_path: Path to existing Stage 1 .pth file

    Returns:
        Dictionary with experimental results
    """

    if not os.path.exists(pretrained_weights_path):
        print(f"❌ ERROR: Pretrained weights not found at: {pretrained_weights_path}")
        print("Available checkpoint files:")
        if os.path.exists("checkpoints"):
            for f in os.listdir("checkpoints"):
                if f.endswith('.pth'):
                    print(f"   checkpoints/{f}")
        return None

    print(f"🎬 Using existing pretrained weights: {pretrained_weights_path}")

    # Run FiLM training experiments
    experiments = {}

    # Experiment 1: Linear FiLM generator
    print(f"\n🧪 EXPERIMENT 1: Linear FiLM Generator")
    exp1_result = run_stage2_film_training(
        pretrained_unet_weights_path=pretrained_weights_path,
        num_epochs_phase_a=10,
        num_epochs_phase_b=30,
        batch_size=4,
        lr_film_generator=1e-4,
        film_generator_mlp_type='linear',
        experiment_name_prefix="FiLM_Exp1_Linear",
        use_film_reg=True,
        lambda_gamma_res=0.005,
        lambda_beta_res=0.0005
    )
    experiments['linear_film'] = exp1_result

    # Experiment 2: 2-layer FiLM generator
    print(f"\n🧪 EXPERIMENT 2: 2-Layer FiLM Generator")
    exp2_result = run_stage2_film_training(
        pretrained_unet_weights_path=pretrained_weights_path,
        num_epochs_phase_a=10,
        num_epochs_phase_b=30,
        batch_size=4,
        lr_film_generator=1e-4,
        film_generator_mlp_type='2_layer',
        experiment_name_prefix="FiLM_Exp2_2Layer",
        use_film_reg=True,
        lambda_gamma_res=0.005,
        lambda_beta_res=0.0005
    )
    experiments['2layer_film'] = exp2_result

    # Experiment 3: Higher FiLM learning rate
    print(f"\n🧪 EXPERIMENT 3: Higher FiLM LR")
    exp3_result = run_stage2_film_training(
        pretrained_unet_weights_path=pretrained_weights_path,
        num_epochs_phase_a=10,
        num_epochs_phase_b=30,
        batch_size=4,
        lr_film_generator=2e-4,  # Higher LR
        film_generator_mlp_type='linear',
        experiment_name_prefix="FiLM_Exp3_HighLR",
        use_film_reg=True,
        lambda_gamma_res=0.005,
        lambda_beta_res=0.0005
    )
    experiments['high_lr_film'] = exp3_result

    # Analyze results
    print(f"\n📊 FILM EXPERIMENT RESULTS SUMMARY")
    print("=" * 60)

    best_experiment = None
    best_mape = float('inf')

    for exp_name, result in experiments.items():
        if result and 'best_mape_phase_b' in result:
            mape = result['best_mape_phase_b']
            print(f"{exp_name:15}: {mape:.4f}% MAPE")

            if mape < best_mape:
                best_mape = mape
                best_experiment = exp_name
        else:
            print(f"{exp_name:15}: FAILED")

    if best_experiment:
        print(f"\n🏆 BEST EXPERIMENT: {best_experiment}")
        print(f"   Best MAPE: {best_mape:.4f}%")
        print(f"   Model: {experiments[best_experiment]['final_model_path']}")

    return experiments


