# === UNIFIED FiLM-AWARE TRAINING FUNCTION ===
# This function resolves the training loop duality by providing a single,
# comprehensive training loop that handles all FiLM-specific requirements

# REPLACE the existing train_with_film_awareness function with this W&B-FREE version.
# =============================================================================
# GRADIENT CENTRALIZATION (GC) UTILITY
# =============================================================================

def apply_gradient_centralization(model):
    """
    Applies Gradient Centralization (GC) in-place to the gradients of a model.
    This function should be called after loss.backward() and before optimizer.step().

    For GCSAM, it is called after the first loss.backward() and before optimizer.first_step().

    Args:
        model (torch.nn.Module): The model with populated .grad attributes.
    """
    # Iterate over all trainable parameters of the model
    for p in model.parameters():
        # Ensure the parameter has a gradient and requires one
        if p.grad is not None and p.requires_grad:
            # GC is typically applied to weight tensors (rank >= 2), not 1D bias vectors.
            if p.grad.ndim >= 2:
                # 1. Identify the dimensions to centralize over.
                #    For a weight tensor W, we centralize gradients for each output unit.
                #    This means we compute the mean over all dimensions except the first (output dimension).
                #    e.g., Conv2D weight (out_ch, in_ch, H, W) -> mean over dims (1, 2, 3)
                #    e.g., Linear weight (out_feat, in_feat) -> mean over dim 1
                dims_to_reduce = tuple(range(1, p.grad.ndim))

                # 2. Compute the mean of the gradients over the identified dimensions.
                #    keepdim=True ensures the mean tensor has the same number of dimensions
                #    as the original gradient, which is necessary for broadcasting.
                mean = torch.mean(p.grad, dim=dims_to_reduce, keepdim=True)

                # 3. Subtract the mean from the gradient in-place.
                #    .sub_() is an in-place operation, which is memory-efficient.
                p.grad.sub_(mean)



def train_with_film_awareness(
    experiment_name, model, train_loader, val_loader, criterion,
    optimizer, num_epochs, device, calculate_mape_func,
    lr_scheduler=None, config=None, checkpoint_freq=10,
    curriculum_simple_epochs=0
):
    """
    ✅ CORRECTED & UNIFIED FiLM-AWARE TRAINING LOOP ✅

    This version correctly handles:
    - Passing the model to the criterion for FiLM regularization.
    - Storing initial LRs for a correct warm-up.
    - Differential gradient clipping and TQDM progress bars.
    - **Curriculum Learning via criterion.set_epoch()**
    """
    use_curriculum = hasattr(criterion, 'set_epoch') and curriculum_simple_epochs > 0
    if use_curriculum:
        print(f"   📚 Curriculum enabled: {curriculum_simple_epochs} epochs simple → full hybrid")


    if config is None:
        config = {}

    history = {'train_loss': [], 'val_mape': [], 'film_reg': []}
    best_val_mape = float('inf')
    best_model_path = None

    # --- Correctly setup for LR Warm-up ---
    warmup_steps = config.get('warmup_steps', 1000)
    initial_lrs = {}
    if warmup_steps > 0:
        for i, group in enumerate(optimizer.param_groups):
            # Store the original LR for each group that needs warm-up
            if group.get('apply_warmup', False):
                initial_lrs[i] = group['lr']
                group['lr'] = initial_lrs[i] * 0.01
                print(f"   🌡️ Warm-up enabled for group '{group.get('group_name', i)}': LR will ramp from {group['lr']:.2e} to {initial_lrs[i]:.2e}")

    global_step = 0
    for epoch in range(num_epochs):
        # === CURRICULUM LEARNING: Set current epoch ===
        if use_curriculum and hasattr(criterion, 'set_epoch'):
            criterion.set_epoch(epoch)
            if epoch == curriculum_simple_epochs:
                print(f"   🎓 Curriculum Phase Complete! Switching to full hybrid loss at epoch {epoch+1}")

        model.train()

        # ========================================================
        # === ✅ START OF FIX: SET CURRENT EPOCH FOR CURRICULUM ===
        # ========================================================
        # This tells the loss function which epoch we are on, allowing it
        # to switch from simple to complex loss at the right time.
        if hasattr(criterion, 'set_epoch'):
            criterion.set_epoch(epoch)
            # You can now use curriculum_simple_epochs to check for the transition
            if hasattr(criterion, 'start_simple') and criterion.start_simple and epoch == curriculum_simple_epochs:
                 print(f"   🔄 Curriculum Transition: Switched to full hybrid loss at epoch {epoch}.")
        # ======================================================
        # === ✅ END OF FIX                                   ===
        # ======================================================

        # --- TRAINING LOOP ---
        progress_bar = tqdm(train_loader, desc=f"Epoch {epoch + 1}/{num_epochs} [Train]", leave=False)
        for i, (inputs, targets) in enumerate(progress_bar):
            inputs, targets = inputs.to(device), targets.to(device)

            # LR Warm-up logic
            if warmup_steps > 0 and global_step < warmup_steps:
                lr_scale = min(1.0, (global_step + 1) / warmup_steps)
                for group_idx, initial_lr in initial_lrs.items():
                    optimizer.param_groups[group_idx]['lr'] = initial_lr * lr_scale

            is_sam = hasattr(optimizer, 'first_step')

            if is_sam:
                # SAM requires two forward passes with BatchNorm handling
                # First forward pass (ascent step) - ALLOW BatchNorm updates
                enable_running_stats(model)  # ✅ FIX: Enable BN stats updates
                loss_dict = criterion(model(inputs), targets, model_for_film_params=model)
                total_loss = loss_dict['total']
                total_loss.backward()
                # 🔥 GCSAM: Apply Gradient Centralization before SAM first step
                use_gc = config.get('use_gc', False) if config is not None else False
                if use_gc:
                    apply_gradient_centralization(model)
                optimizer.first_step(zero_grad=True)

                # Second forward pass (descent step) - FREEZE BatchNorm stats
                disable_running_stats(model)  # ✅ FIX: Disable BN stats updates
                loss_dict = criterion(model(inputs), targets, model_for_film_params=model)
                total_loss = loss_dict['total']
                film_reg_loss = loss_dict.get('film_reg', torch.tensor(0.0))
                total_loss.backward()
                optimizer.second_step(zero_grad=True)

            else:
                # Standard optimizer step
                optimizer.zero_grad()

                outputs = model(inputs)
                try:
                    loss_dict = criterion(outputs, targets, model_for_film_params=model)
                except TypeError:
                    loss_dict = criterion(outputs, targets)

                total_loss = loss_dict['total']
                film_reg_loss = loss_dict.get('film_reg', torch.tensor(0.0))

                total_loss.backward()

                # Differential Gradient Clipping
                use_grad_clipping = config.get('use_grad_clipping', True)
                if use_grad_clipping:
                    film_params_ids = {id(p) for p in model.film_bottleneck_modulator.parameters()} if hasattr(model, 'film_bottleneck_modulator') else set()
                    clip_film = config.get('gradient_clip_film', 1.0)
                    clip_others = config.get('gradient_clip_others', 5.0)

                    for group in optimizer.param_groups:
                        is_film_group = any(id(p) in film_params_ids for p in group['params'])
                        clip_value = clip_film if is_film_group else clip_others
                        torch.nn.utils.clip_grad_norm_(group['params'], clip_value)

                optimizer.step()
            global_step += 1

            # ✅ FIX: Step CosineAnnealing scheduler per batch (after curriculum)
            if (lr_scheduler is not None and
                isinstance(lr_scheduler, torch.optim.lr_scheduler.CosineAnnealingWarmRestarts) and
                epoch >= curriculum_simple_epochs):
                effective_epoch = epoch - curriculum_simple_epochs
                fractional_epoch = effective_epoch + i / len(train_loader)
                lr_scheduler.step(fractional_epoch)

            progress_bar.set_postfix(loss=f"{total_loss.item():.4f}", film_reg=f"{film_reg_loss.item():.4f}")
        # --- VALIDATION PHASE ---
        model.eval()
        total_val_mape = 0
        with torch.no_grad():
            for inputs, targets in tqdm(val_loader, desc=f"Epoch {epoch + 1}/{num_epochs} [Val]", leave=False):
                inputs, targets_torch = inputs.to(device), targets.to(device)
                outputs = model(inputs)

                outputs_np = outputs.squeeze(1).cpu().numpy()
                targets_np = targets_torch.squeeze(1).cpu().numpy()
                # Ensure calculate_mape is called per-item in batch
                for i in range(outputs_np.shape[0]):
                    total_val_mape += calculate_mape(targets_np[i], outputs_np[i])

        avg_val_mape = total_val_mape / len(val_loader.dataset)
        history['val_mape'].append(avg_val_mape)

        print(f"   Epoch {epoch + 1}/{num_epochs} -> Val MAPE: {avg_val_mape:.4f}%")

        if avg_val_mape < best_val_mape:
            best_val_mape = avg_val_mape
            best_model_path = os.path.join(CHECKPOINT_DIR, f"{experiment_name}_best_mape.pth")
            torch.save(model.state_dict(), best_model_path)
            print(f"   ✨ New best MAPE! Model saved to {best_model_path}")

        if lr_scheduler is not None:
            # Only activate scheduler AFTER curriculum phase ends
            if epoch >= curriculum_simple_epochs:
                # ✅ SAM-compatible optimizer targeting
                target_optimizer = optimizer.base_optimizer if hasattr(optimizer, 'base_optimizer') else optimizer
                prev_lr = target_optimizer.param_groups[0]['lr']

                if isinstance(lr_scheduler, torch.optim.lr_scheduler.ReduceLROnPlateau):
                    # Standard ReduceLROnPlateau
                    lr_scheduler.step(avg_val_mape)
                    current_lr = target_optimizer.param_groups[0]['lr']
                    if current_lr < prev_lr:
                        print(f"   📉 ReduceLROnPlateau: LR reduced {prev_lr:.2e} → {current_lr:.2e}")
                    else:
                        print(f"   ➡️  ReduceLROnPlateau: LR unchanged at {current_lr:.2e}")

                elif isinstance(lr_scheduler, PlateauToCosineScheduler):
                    # Get the monitored group index from scheduler
                    monitored_group_idx = lr_scheduler.threshold_group_index
                    prev_lr = target_optimizer.param_groups[monitored_group_idx]['lr']

                    lr_scheduler.step(avg_val_mape)
                    current_lr = target_optimizer.param_groups[monitored_group_idx]['lr']
                    group_name = target_optimizer.param_groups[monitored_group_idx].get('group_name', f'Group {monitored_group_idx}')

                    if lr_scheduler.switched:
                        print(f"   🌊 Cosine phase ({group_name}): LR={current_lr:.2e} (smooth descent)")
                    else:
                        if current_lr < prev_lr:
                            print(f"   📉 Plateau phase ({group_name}): LR reduced {prev_lr:.2e} → {current_lr:.2e}")
                        else:
                            print(f"   ➡️  Plateau phase ({group_name}): LR={current_lr:.2e}")

                elif isinstance(lr_scheduler, torch.optim.lr_scheduler.CosineAnnealingWarmRestarts):
                    # CosineAnnealingWarmRestarts is stepped per-batch, not per-epoch
                    current_lr = target_optimizer.param_groups[0]['lr']
                    print(f"   🌊 CosineWarmRestarts: LR={current_lr:.2e}")

                else:
                    # Other schedulers
                    lr_scheduler.step()
                    current_lr = target_optimizer.param_groups[0]['lr']
                    print(f"   🎯 {type(lr_scheduler).__name__}: LR={current_lr:.2e}")

            else:
                print(f"   ⏸️  Scheduler inactive (curriculum epoch {epoch+1}/{curriculum_simple_epochs})")

    final_result = {
        'best_mape': best_val_mape,
        'final_model_path': best_model_path,
        'history': history
    }
    return final_result


def train_with_curriculum_fixed(*args, **kwargs):
    """
    Compatibility wrapper that redirects to the unified FiLM-aware training function.
    This ensures all existing code continues to work while benefiting from FiLM awareness.
    """
    # Ensure 'config' is passed or defaults to an empty dict if not present (FIX 2)
    return train_with_film_awareness(*args, **kwargs)

