def test_original_champion_overfitting():
    """
    Test the original Extended Champion model for overfitting patterns.
    Compare with SWA Champion to see which generalizes better.
    """
    print("🔬 COMPREHENSIVE OVERFITTING ANALYSIS")
    print("👑 Testing Original Extended Champion Model")
    print("=" * 70)

    # Original Champion model path
    original_champion_path = "/content/Extended_Absolute_Champion_best_mape.pth"

    # Check if model exists
    if not os.path.exists(original_champion_path):
        print(f"❌ Original champion model not found at: {original_champion_path}")
        print("Available checkpoints:")
        checkpoint_dir = "checkpoints"
        if os.path.exists(checkpoint_dir):
            for f in os.listdir(checkpoint_dir):
                if f.endswith('.pth'):
                    print(f"   - {f}")
        return None

    # 1. Generalization testing
    print("\n1️⃣  GENERALIZATION TESTING - ORIGINAL CHAMPION")
    original_gen_results, original_gen_assessment = test_generalization_new_split_original(
        original_champion_path, num_tests=5
    )

    # 2. Visual inspection
    print("\n2️⃣  VISUAL INSPECTION - ORIGINAL CHAMPION")
    original_residuals, original_smoothness = visual_overfitting_check_original(
        original_champion_path, num_samples=8
    )

    return {
        'generalization': original_gen_results,
        'visual_analysis': {'residuals': original_residuals, 'smoothness': original_smoothness},
        'generalization_assessment': original_gen_assessment
    }

def test_generalization_new_split_original(model_path, num_tests=3):
    """
    Test original champion model generalization on multiple fresh data splits.
    """
    print(f"🔄 GENERALIZATION TESTING: {num_tests} fresh data splits")
    print("=" * 60)

    # Load original champion model (NOT SWA)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = BaselineUNet(5, 1).to(device)  # Original champion architecture

    # Load regular model (not SWA)
    model.load_state_dict(torch.load(model_path, map_location=device))
    print(f"✅ Loaded original champion model from {model_path}")

    model.eval()

    test_results = []

    for test_idx in range(num_tests):
        print(f"\n📊 Test Split {test_idx + 1}/{num_tests}")

        # Create new random split
        train_loader, val_loader = setup_phase2_data_loaders(
            test_size=0.2,
            batch_size=4,
            random_state=42 + test_idx  # Different random seed
        )

        # Evaluate on this split's validation set
        total_mape = 0.0
        total_samples = 0
        sample_mapes = []

        with torch.no_grad():
            for inputs, targets in tqdm(val_loader, desc=f"Evaluating Split {test_idx + 1}", leave=False):
                inputs, targets = inputs.to(device), targets.to(device)
                outputs = model(inputs)

                # Calculate MAPE for each sample
                outputs_np = outputs.squeeze(1).cpu().numpy()
                targets_np = targets.squeeze(1).cpu().numpy()

                for i in range(outputs_np.shape[0]):
                    sample_mape = calculate_mape(targets_np[i], outputs_np[i])
                    sample_mapes.append(sample_mape)
                    total_mape += sample_mape
                    total_samples += 1

        split_mape = total_mape / total_samples
        split_std = np.std(sample_mapes)

        test_results.append({
            'split_idx': test_idx,
            'mape': split_mape,
            'std': split_std,
            'min_mape': np.min(sample_mapes),
            'max_mape': np.max(sample_mapes),
            'num_samples': total_samples
        })

        print(f"   MAPE: {split_mape:.4f}% (±{split_std:.4f}%)")
        print(f"   Range: {np.min(sample_mapes):.4f}% - {np.max(sample_mapes):.4f}%")

    # Analysis
    mapes = [r['mape'] for r in test_results]
    overall_mean = np.mean(mapes)
    overall_std = np.std(mapes)

    print(f"\n🎯 GENERALIZATION ANALYSIS:")
    print(f"   Mean MAPE across splits: {overall_mean:.4f}% (±{overall_std:.4f}%)")
    print(f"   Best split: {np.min(mapes):.4f}%")
    print(f"   Worst split: {np.max(mapes):.4f}%")
    print(f"   Coefficient of variation: {(overall_std/overall_mean)*100:.2f}%")

    # Overfitting assessment
    cv = (overall_std/overall_mean)*100
    if cv < 5:
        assessment = "✅ EXCELLENT GENERALIZATION"
    elif cv < 10:
        assessment = "⚠️  GOOD GENERALIZATION"
    else:
        assessment = "🚨 POOR GENERALIZATION (LIKELY OVERFITTING)"

    print(f"   Assessment: {assessment}")

    return test_results, assessment

def visual_overfitting_check_original(model_path, num_samples=8):
    """
    Visual inspection for overfitting patterns in original champion predictions.
    """
    print("👁️  VISUAL OVERFITTING INSPECTION - ORIGINAL CHAMPION")
    print("=" * 50)

    # Load model and data
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = BaselineUNet(5, 1).to(device)  # Original champion architecture

    # Load regular model (not SWA)
    model.load_state_dict(torch.load(model_path, map_location=device))
    model.eval()

    # Get validation data
    _, val_loader = setup_phase2_data_loaders(batch_size=1, random_state=42)

    # Collect predictions and analyze patterns
    residual_patterns = []
    prediction_smoothness = []
    predictions = []
    targets = []
    residuals = []
    sample_mapes = []

    # ✅ Create 2 rows - residuals (top) + scatter plots (bottom)
    fig, axes = plt.subplots(2, 4, figsize=(20, 10))

    with torch.no_grad():
        for idx, (inputs, targets_batch) in enumerate(val_loader):
            if idx >= 8:  # Get 8 samples
                break

            inputs, targets_batch = inputs.to(device), targets_batch.to(device)
            outputs = model(inputs)

            # Convert to numpy
            pred = outputs.squeeze().cpu().numpy()
            true = targets_batch.squeeze().cpu().numpy()
            residual = pred - true

            # Store for analysis
            predictions.append(pred)
            targets.append(true)
            residuals.append(residual)
            sample_mapes.append(calculate_mape(true, pred))

            # Analyze patterns
            residual_patterns.append(np.std(residual))

            # Check for unrealistic smoothness (overfitting sign)
            pred_grad_h = np.gradient(pred, axis=0)
            pred_grad_v = np.gradient(pred, axis=1)
            smoothness = np.mean(np.abs(pred_grad_h)) + np.mean(np.abs(pred_grad_v))
            prediction_smoothness.append(smoothness)

            # Plot residual heatmaps (TOP ROW)
            if idx < 4:
                im = axes[0, idx].imshow(residual, cmap='RdBu_r', vmin=-0.4, vmax=0.4)
                axes[0, idx].set_title(f'Original Residual {idx+1}\nMAPE: {sample_mapes[idx]:.4f}%')
                axes[0, idx].axis('off')

            # Plot scatter plots (BOTTOM ROW)
            if idx < 4:
                pred_flat = pred.flatten()
                true_flat = true.flatten()

                # Scatter plot with proper sampling for performance
                n_points = min(5000, len(pred_flat))
                indices = np.random.choice(len(pred_flat), n_points, replace=False)

                axes[1, idx].scatter(true_flat[indices], pred_flat[indices],
                                   alpha=0.5, s=1, c='red')  # Red for original champion

                # Perfect prediction line
                min_val = min(true_flat.min(), pred_flat.min())
                max_val = max(true_flat.max(), pred_flat.max())
                axes[1, idx].plot([min_val, max_val], [min_val, max_val], 'k--', lw=2)

                axes[1, idx].set_xlabel('True Velocity')
                axes[1, idx].set_ylabel('Predicted Velocity')
                axes[1, idx].set_title(f'Original Pred vs True {idx+1}')
                axes[1, idx].grid(True, alpha=0.3)

    plt.tight_layout()
    plt.suptitle('ORIGINAL CHAMPION - Prediction Residuals (Blue=Underprediction, Red=Overprediction)', y=1.02)
    plt.show()

    # Analysis
    residual_consistency = np.std(residual_patterns) / np.mean(residual_patterns)
    smoothness_consistency = np.std(prediction_smoothness) / np.mean(prediction_smoothness)

    print(f"📊 VISUAL ANALYSIS:")
    print(f"   Residual pattern consistency: {residual_consistency:.3f}")
    print(f"   Prediction smoothness consistency: {smoothness_consistency:.3f}")

    if residual_consistency < 0.2 and smoothness_consistency < 0.3:
        print("   ✅ Consistent prediction patterns - No obvious overfitting")
    elif residual_consistency < 0.4:
        print("   ⚠️  Some pattern variation - Monitor closely")
    else:
        print("   🚨 High pattern variation - Possible overfitting")

    return residual_patterns, prediction_smoothness

def compare_swa_vs_original_overfitting():
    """
    Direct comparison of SWA Champion vs Original Champion overfitting.
    """
    print("⚖️  SWA vs ORIGINAL CHAMPION OVERFITTING COMPARISON")
    print("=" * 70)

    # Test both models
    print("Testing SWA Champion...")
    swa_results = comprehensive_overfitting_test("/content/drive/MyDrive/colab/checkpoints/CHAMPION_SWA_MODEL.pth")

    print("\nTesting Original Champion...")
    original_results = test_original_champion_overfitting()

    # Compare results
    print("\n" + "=" * 70)
    print("🏆 FINAL COMPARISON RESULTS")
    print("=" * 70)

    if swa_results and original_results:
        # Compare generalization
        swa_gen = swa_results['generalization']
        orig_gen = original_results['generalization']

        swa_mapes = [r['mape'] for r in swa_gen]
        orig_mapes = [r['mape'] for r in orig_gen]

        swa_mean = np.mean(swa_mapes)
        orig_mean = np.mean(orig_mapes)
        swa_std = np.std(swa_mapes)
        orig_std = np.std(orig_mapes)

        print(f"📊 GENERALIZATION COMPARISON:")
        print(f"   SWA Champion:      {swa_mean:.4f}% (±{swa_std:.4f}%)")
        print(f"   Original Champion: {orig_mean:.4f}% (±{orig_std:.4f}%)")

        if swa_std < orig_std:
            print(f"   🏆 Winner: SWA (more stable - {((orig_std-swa_std)/orig_std*100):.1f}% less variation)")
        elif orig_std < swa_std:
            print(f"   🏆 Winner: Original ({((swa_std-orig_std)/swa_std*100):.1f}% less variation)")
        else:
            print(f"   🤝 Tie: Similar stability")

        # Compare performance
        if swa_mean < orig_mean:
            improvement = ((orig_mean - swa_mean) / orig_mean) * 100
            print(f"   📈 SWA Performance: {improvement:.2f}% better")
        else:
            degradation = ((swa_mean - orig_mean) / orig_mean) * 100
            print(f"   📉 SWA Performance: {degradation:.2f}% worse")

    print("=" * 70)

    return swa_results, original_results


def analyze_overfitting_from_history(history, model_name="SWA_Champion"):
    """
    Analyze training history to detect overfitting patterns.

    Args:
        history: Training history from your train_with_film_awareness function
        model_name: Name for the analysis
    """
    print(f"🔍 OVERFITTING ANALYSIS: {model_name}")
    print("=" * 60)

    if 'val_mape' not in history or 'train_loss' not in history:
        print("❌ Insufficient history data for analysis")
        return None

    val_mape = history['val_mape']
    train_loss = history['train_loss']

    # Find best epoch and check for divergence
    best_epoch = np.argmin(val_mape)
    best_mape = val_mape[best_epoch]

    # Check for early peak (sign of overfitting)
    total_epochs = len(val_mape)
    early_peak = best_epoch < (total_epochs * 0.7)  # Peak in first 70%

    # Check for validation degradation after best
    if best_epoch < total_epochs - 5:  # At least 5 epochs after best
        post_best_mape = val_mape[best_epoch + 5:]
        degradation = np.mean(post_best_mape) - best_mape
        significant_degradation = degradation > (best_mape * 0.05)  # >5% relative increase
    else:
        degradation = 0
        significant_degradation = False

    # Check training loss trend (should decrease consistently)
    train_loss_smooth = np.convolve(train_loss, np.ones(5)/5, mode='valid')  # 5-epoch moving average
    train_loss_increasing = len(train_loss_smooth) > 10 and train_loss_smooth[-5:].mean() > train_loss_smooth[-10:-5].mean()

    print(f"📊 ANALYSIS RESULTS:")
    print(f"   Best MAPE: {best_mape:.4f}% at epoch {best_epoch + 1}")
    print(f"   Total epochs: {total_epochs}")
    print(f"   Early peak (< 70% training): {'⚠️  YES' if early_peak else '✅ NO'}")
    print(f"   Post-best degradation: {degradation:.6f} ({'⚠️  SIGNIFICANT' if significant_degradation else '✅ MINOR'})")
    print(f"   Training loss trend: {'⚠️  INCREASING' if train_loss_increasing else '✅ DECREASING'}")

    # Overall assessment
    overfitting_indicators = sum([early_peak, significant_degradation, train_loss_increasing])

    if overfitting_indicators == 0:
        assessment = "✅ NO OVERFITTING DETECTED"
    elif overfitting_indicators == 1:
        assessment = "⚠️  MILD OVERFITTING POSSIBLE"
    else:
        assessment = "🚨 OVERFITTING LIKELY"

    print(f"\n🎯 OVERALL ASSESSMENT: {assessment}")

    # Plot analysis
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(15, 5))

    # Validation MAPE curve
    ax1.plot(val_mape, 'b-', linewidth=2, label='Validation MAPE')
    ax1.axvline(best_epoch, color='r', linestyle='--', alpha=0.7, label=f'Best Epoch ({best_epoch + 1})')
    ax1.set_xlabel('Epoch')
    ax1.set_ylabel('Validation MAPE (%)')
    ax1.set_title(f'{model_name} - Validation MAPE')
    ax1.legend()
    ax1.grid(True, alpha=0.3)

    # Training loss curve
    ax2.plot(train_loss, 'g-', linewidth=2, label='Training Loss')
    if len(train_loss_smooth) > 0:
        ax2.plot(range(2, len(train_loss_smooth) + 2), train_loss_smooth, 'r--', alpha=0.7, label='5-Epoch Moving Avg')
    ax2.set_xlabel('Epoch')
    ax2.set_ylabel('Training Loss')
    ax2.set_title(f'{model_name} - Training Loss')
    ax2.legend()
    ax2.grid(True, alpha=0.3)

    plt.tight_layout()
    plt.show()

    return {
        'best_mape': best_mape,
        'best_epoch': best_epoch,
        'early_peak': early_peak,
        'degradation': degradation,
        'significant_degradation': significant_degradation,
        'overfitting_score': overfitting_indicators,
        'assessment': assessment
    }


def test_generalization_new_split(model_path, num_tests=3):
    """
    Test model generalization on multiple fresh data splits.

    Args:
        model_path: Path to your SWA champion model
        num_tests: Number of different data splits to test
    """
    print(f"🔄 GENERALIZATION TESTING: {num_tests} fresh data splits")
    print("=" * 60)

    # Load your champion SWA model
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = CompleteSincGAT_UNet(film_generator_mlp_type='2_layer').to(device)

    # Load SWA model (note: different loading for AveragedModel)
    try:
        import torch.optim.swa_utils as swa_utils
        swa_model = swa_utils.AveragedModel(model)
        swa_model.load_state_dict(torch.load(model_path, map_location=device))
        model = swa_model
        print(f"✅ Loaded SWA model from {model_path}")
    except:
        # Fallback to regular model loading
        model.load_state_dict(torch.load(model_path, map_location=device))
        print(f"✅ Loaded regular model from {model_path}")

    model.eval()

    test_results = []

    for test_idx in range(num_tests):
        print(f"\n📊 Test Split {test_idx + 1}/{num_tests}")

        # Create new random split
        train_loader, val_loader = setup_phase2_data_loaders(
            test_size=0.2,
            batch_size=4,
            random_state=42 + test_idx  # Different random seed
        )

        # Evaluate on this split's validation set
        total_mape = 0.0
        total_samples = 0
        sample_mapes = []

        with torch.no_grad():
            for inputs, targets in tqdm(val_loader, desc=f"Evaluating Split {test_idx + 1}", leave=False):
                inputs, targets = inputs.to(device), targets.to(device)
                outputs = model(inputs)

                # Calculate MAPE for each sample
                outputs_np = outputs.squeeze(1).cpu().numpy()
                targets_np = targets.squeeze(1).cpu().numpy()

                for i in range(outputs_np.shape[0]):
                    sample_mape = calculate_mape(targets_np[i], outputs_np[i])
                    sample_mapes.append(sample_mape)
                    total_mape += sample_mape
                    total_samples += 1

        split_mape = total_mape / total_samples
        split_std = np.std(sample_mapes)

        test_results.append({
            'split_idx': test_idx,
            'mape': split_mape,
            'std': split_std,
            'min_mape': np.min(sample_mapes),
            'max_mape': np.max(sample_mapes),
            'num_samples': total_samples
        })

        print(f"   MAPE: {split_mape:.4f}% (±{split_std:.4f}%)")
        print(f"   Range: {np.min(sample_mapes):.4f}% - {np.max(sample_mapes):.4f}%")

    # Analysis
    mapes = [r['mape'] for r in test_results]
    overall_mean = np.mean(mapes)
    overall_std = np.std(mapes)

    print(f"\n🎯 GENERALIZATION ANALYSIS:")
    print(f"   Mean MAPE across splits: {overall_mean:.4f}% (±{overall_std:.4f}%)")
    print(f"   Best split: {np.min(mapes):.4f}%")
    print(f"   Worst split: {np.max(mapes):.4f}%")
    print(f"   Coefficient of variation: {(overall_std/overall_mean)*100:.2f}%")

    # Overfitting assessment
    cv = (overall_std/overall_mean)*100
    if cv < 5:
        assessment = "✅ EXCELLENT GENERALIZATION"
    elif cv < 10:
        assessment = "⚠️  GOOD GENERALIZATION"
    else:
        assessment = "🚨 POOR GENERALIZATION (LIKELY OVERFITTING)"

    print(f"   Assessment: {assessment}")

    return test_results, assessment


def visual_overfitting_check(model_path, num_samples=8):
    """
    Visual inspection for overfitting patterns in predictions.

    Args:
        model_path: Path to your model
        num_samples: Number of samples to visualize
    """
    print("👁️  VISUAL OVERFITTING INSPECTION")
    print("=" * 50)

    # Load model and data
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = CompleteSincGAT_UNet(film_generator_mlp_type='2_layer').to(device)

    try:
        import torch.optim.swa_utils as swa_utils
        swa_model = swa_utils.AveragedModel(model)
        swa_model.load_state_dict(torch.load(model_path, map_location=device))
        model = swa_model
    except:
        model.load_state_dict(torch.load(model_path, map_location=device))

    model.eval()

    # Get validation data
    _, val_loader = setup_phase2_data_loaders(batch_size=1, random_state=42)

    # Collect predictions and analyze patterns
    residual_patterns = []
    prediction_smoothness = []

    fig, axes = plt.subplots(4, min(num_samples//2, 4), figsize=(16, 12))
    axes = axes.flatten()

    with torch.no_grad():
        for idx, (inputs, targets) in enumerate(val_loader):
            if idx >= num_samples:
                break

            inputs, targets = inputs.to(device), targets.to(device)
            outputs = model(inputs)

            # Convert to numpy
            pred = outputs.squeeze().cpu().numpy()
            true = targets.squeeze().cpu().numpy()
            residual = pred - true

            # Analyze patterns
            residual_patterns.append(np.std(residual))

            # Check for unrealistic smoothness (overfitting sign)
            pred_grad_h = np.gradient(pred, axis=0)
            pred_grad_v = np.gradient(pred, axis=1)
            smoothness = np.mean(np.abs(pred_grad_h)) + np.mean(np.abs(pred_grad_v))
            prediction_smoothness.append(smoothness)

            # Plot if space available
            if idx < len(axes):
                im = axes[idx].imshow(residual, cmap='RdBu_r', vmin=-0.5, vmax=0.5)
                axes[idx].set_title(f'Residual {idx+1}\nMAPE: {calculate_mape(true, pred):.4f}%')
                axes[idx].axis('off')
                plt.colorbar(im, ax=axes[idx], fraction=0.046, pad=0.04)

    plt.tight_layout()
    plt.suptitle('Prediction Residuals (Blue=Underprediction, Red=Overprediction)', y=1.02)
    plt.show()

    # Analysis
    residual_consistency = np.std(residual_patterns) / np.mean(residual_patterns)
    smoothness_consistency = np.std(prediction_smoothness) / np.mean(prediction_smoothness)

    print(f"📊 VISUAL ANALYSIS:")
    print(f"   Residual pattern consistency: {residual_consistency:.3f}")
    print(f"   Prediction smoothness consistency: {smoothness_consistency:.3f}")

    if residual_consistency < 0.2 and smoothness_consistency < 0.3:
        print("   ✅ Consistent prediction patterns - No obvious overfitting")
    elif residual_consistency < 0.4:
        print("   ⚠️  Some pattern variation - Monitor closely")
    else:
        print("   🚨 High pattern variation - Possible overfitting")

    return residual_patterns, prediction_smoothness

def comprehensive_overfitting_test(swa_model_path):
    """
    Run complete overfitting detection pipeline on your SWA champion.

    Args:
        swa_model_path: Path to your 0.0655% MAPE SWA model
    """
    print("🔬 COMPREHENSIVE OVERFITTING ANALYSIS")
    print("🏆 Testing SWA Champion Model (0.0655% MAPE)")
    print("=" * 70)

    # 1. Generalization testing
    print("\n1️⃣  GENERALIZATION TESTING")
    gen_results, gen_assessment = test_generalization_new_split(swa_model_path, num_tests=5)

    # 2. Visual inspection
    print("\n2️⃣  VISUAL INSPECTION")
    residuals, smoothness =visual_overfitting_check_fixed(swa_model_path, num_samples=8)

    # 3. If you have training history, analyze it
    # Note: You'd need to save the history from your SWA training
    # print("\n3️⃣  TRAINING HISTORY ANALYSIS")
    # if 'swa_history' in globals():
    #     hist_analysis = analyze_overfitting_from_history(swa_history, "SWA_Champion")

    # Final assessment
    print("\n🎯 FINAL OVERFITTING ASSESSMENT")
    print("=" * 40)

    gen_score = 0 if "EXCELLENT" in gen_assessment else (1 if "GOOD" in gen_assessment else 2)
    visual_score = 0 if np.std(residuals)/np.mean(residuals) < 0.2 else (1 if np.std(residuals)/np.mean(residuals) < 0.4 else 2)

    total_score = gen_score + visual_score

    if total_score == 0:
        final_assessment = "✅ NO OVERFITTING - EXCELLENT GENERALIZATION"
    elif total_score <= 2:
        final_assessment = "⚠️  MINIMAL OVERFITTING - GOOD GENERALIZATION"
    else:
        final_assessment = "🚨 POSSIBLE OVERFITTING - REQUIRES ATTENTION"

    print(f"Generalization: {gen_assessment}")
    print(f"Visual patterns: {'Consistent' if visual_score == 0 else 'Variable'}")
    print(f"\n🏆 OVERALL: {final_assessment}")

    return {
        'generalization': gen_results,
        'visual_analysis': {'residuals': residuals, 'smoothness': smoothness},
        'final_assessment': final_assessment
    }
def visual_overfitting_check_fixed(model_path, num_samples=8):
    """
    Visual inspection for overfitting patterns in predictions - FIXED VERSION.

    Args:
        model_path: Path to your model
        num_samples: Number of samples to visualize
    """
    print("👁️  VISUAL OVERFITTING INSPECTION")
    print("=" * 50)

    # Load model and data
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = CompleteSincGAT_UNet(film_generator_mlp_type='2_layer').to(device)

    try:
        import torch.optim.swa_utils as swa_utils
        swa_model = swa_utils.AveragedModel(model)
        swa_model.load_state_dict(torch.load(model_path, map_location=device))
        model = swa_model
    except:
        model.load_state_dict(torch.load(model_path, map_location=device))

    model.eval()

    # Get validation data
    _, val_loader = setup_phase2_data_loaders(batch_size=1, random_state=42)

    # Collect predictions and analyze patterns
    residual_patterns = []
    prediction_smoothness = []
    predictions = []
    targets = []
    residuals = []
    sample_mapes = []

    # ✅ FIXED: Create 2 rows - residuals (top) + scatter plots (bottom)
    fig, axes = plt.subplots(2, 4, figsize=(20, 10))

    with torch.no_grad():
        for idx, (inputs, targets_batch) in enumerate(val_loader):
            if idx >= 8:  # Get 8 samples
                break

            inputs, targets_batch = inputs.to(device), targets_batch.to(device)
            outputs = model(inputs)

            # Convert to numpy
            pred = outputs.squeeze().cpu().numpy()
            true = targets_batch.squeeze().cpu().numpy()
            residual = pred - true

            # Store for analysis
            predictions.append(pred)
            targets.append(true)
            residuals.append(residual)
            sample_mapes.append(calculate_mape(true, pred))

            # Analyze patterns
            residual_patterns.append(np.std(residual))

            # Check for unrealistic smoothness (overfitting sign)
            pred_grad_h = np.gradient(pred, axis=0)
            pred_grad_v = np.gradient(pred, axis=1)
            smoothness = np.mean(np.abs(pred_grad_h)) + np.mean(np.abs(pred_grad_v))
            prediction_smoothness.append(smoothness)

            # ✅ FIXED: Plot residual heatmaps (TOP ROW)
            if idx < 4:
                im = axes[0, idx].imshow(residual, cmap='RdBu_r', vmin=-0.4, vmax=0.4)
                axes[0, idx].set_title(f'Residual {idx+1}\nMAPE: {sample_mapes[idx]:.4f}%')
                axes[0, idx].axis('off')

            # ✅ FIXED: Plot scatter plots (BOTTOM ROW)
            if idx < 4:
                pred_flat = pred.flatten()
                true_flat = true.flatten()

                # Scatter plot with proper sampling for performance
                n_points = min(5000, len(pred_flat))
                indices = np.random.choice(len(pred_flat), n_points, replace=False)

                axes[1, idx].scatter(true_flat[indices], pred_flat[indices],
                                   alpha=0.5, s=1, c='blue')

                # Perfect prediction line
                min_val = min(true_flat.min(), pred_flat.min())
                max_val = max(true_flat.max(), pred_flat.max())
                axes[1, idx].plot([min_val, max_val], [min_val, max_val], 'r--', lw=2)

                axes[1, idx].set_xlabel('True Velocity')
                axes[1, idx].set_ylabel('Predicted Velocity')
                axes[1, idx].set_title(f'Pred vs True {idx+1}')
                axes[1, idx].grid(True, alpha=0.3)

    plt.tight_layout()
    plt.suptitle('Prediction Residuals (Blue=Underprediction, Red=Overprediction)', y=1.02)
    plt.show()

    # Analysis
    residual_consistency = np.std(residual_patterns) / np.mean(residual_patterns)
    smoothness_consistency = np.std(prediction_smoothness) / np.mean(prediction_smoothness)

    print(f"📊 VISUAL ANALYSIS:")
    print(f"   Residual pattern consistency: {residual_consistency:.3f}")
    print(f"   Prediction smoothness consistency: {smoothness_consistency:.3f}")

    if residual_consistency < 0.2 and smoothness_consistency < 0.3:
        print("   ✅ Consistent prediction patterns - No obvious overfitting")
    elif residual_consistency < 0.4:
        print("   ⚠️  Some pattern variation - Monitor closely")
    else:
        print("   🚨 High pattern variation - Possible overfitting")

    return residual_patterns, prediction_smoothness
